package ai

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

// TestCase is a single AI generated test case.
type TestCase struct {
	Name        string
	Description string
	Args        map[string]string
	Want        map[string]string
	WantErr     bool
}

// Provider is a minimal Ollama-like provider.
type Provider struct {
	Endpoint    string // raw endpoint as configured
	Base        string
	Model       string
	HTTPClient  *http.Client
	GenerateURL string
}

func ValidateEndpoint(endpoint string) error {
	if endpoint == "" {
		return fmt.Errorf("invalid endpoint: endpoint cannot be empty")
	}
	u, err := url.Parse(endpoint)
	if err != nil {
		return fmt.Errorf("invalid endpoint: invalid URL format: %w", err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return fmt.Errorf("invalid endpoint: invalid URL scheme %q: only http and https are allowed", u.Scheme)
	}
	if u.Host == "" {
		return fmt.Errorf("invalid endpoint: URL must include a host")
	}
	return nil
}

func NewProvider(endpoint, model string) (*Provider, error) {
	if err := ValidateEndpoint(endpoint); err != nil {
		return nil, err
	}
	base := strings.TrimRight(endpoint, "/")
	return &Provider{Endpoint: endpoint, Base: base, Model: model, HTTPClient: &http.Client{Timeout: 120 * time.Second}}, nil
}

// Available reports whether the provider tags endpoint responds with 200.
func (p *Provider) Available() bool {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, p.Base+"/api/tags", nil)
	if err != nil {
		return false
	}
	client := &http.Client{Timeout: 2 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return false
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, resp.Body)
	return resp.StatusCode == http.StatusOK
}

type generateRequest struct {
	Model   string `json:"model"`
	Options struct {
		Seed        int `json:"seed"`
		Temperature int `json:"temperature"`
	} `json:"options"`
	Prompt string `json:"prompt"`
	Stream bool   `json:"stream"`
}

type generateResponse struct {
	Response string `json:"response"`
}

// Generate sends a generate request and returns the textual response.
func (p *Provider) Generate(prompt string) (string, error) {
	var reqBody generateRequest
	reqBody.Model = p.Model
	reqBody.Options.Seed = 42
	reqBody.Options.Temperature = 0
	reqBody.Prompt = prompt
	reqBody.Stream = false
	b, err := json.Marshal(reqBody)
	if err != nil {
		return "", err
	}
	req, err := http.NewRequest(http.MethodPost, p.Base+"/api/generate", bytes.NewReader(b))
	if err != nil {
		return "", err
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := p.HTTPClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		return "", fmt.Errorf("ollama returned %d: %s", resp.StatusCode, string(body))
	}
	var out generateResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("decode response: %w", err)
	}
	return out.Response, nil
}
EOF
