{"command":"cd /workspace && cat > internal/goparser/goparser.go <<'EOF'
package goparser

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"gotestsreimpl/internal/models"
)

// SourceFile is the result of parsing one source file.
type SourceFile struct {
	Header    *models.Header
	Functions []*models.Function
	Path      string
	Dir       string
}

// TestFile is the result of parsing the matching _test.go file.
type TestFile struct {
	Exists    bool
	Header    *models.Header
	FuncNames map[string]bool
	Path      string
}

// Parser parses Go source files.
type Parser struct{}

func New() *Parser { return &Parser{} }

type parsedAST struct {
	path string
	file *ast.File
	src  []byte
	fset *token.FileSet
}

type context struct {
	typeSpecs   map[string]*ast.TypeSpec
	typeParams  map[string]ast.Expr
	specFiles   map[string]bool
	seenUnder   map[string]bool
}

func offset(fset *token.FileSet, pos token.Pos) int {
	return fset.PositionFor(pos, false).Offset
}

func packageComments(f *ast.File) []string {
	var out []string
	for _, g := range f.Comments {
		if g.Pos() >= f.Package {
			continue
		}
		for _, c := range g.List {
			out = append(out, c.Text)
		}
	}
	return out
}

func importsOf(f *ast.File) []*models.Import {
	var out []*models.Import
	for _, spec := range f.Imports {
		name := ""
		if spec.Name != nil {
			name = spec.Name.Name
		}
		out = append(out, &models.Import{Name: name, Path: spec.Path.Value})
	}
	return out
}

// TestPath returns the test file matching a source file.
func TestPath(src string) string {
	if strings.HasSuffix(src, "_test.go") {
		return src
	}
	return strings.TrimSuffix(src, ".go") + "_test.go"
}

func (p *Parser) ParseSource(path string) (*SourceFile, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse source file: ioutil.ReadFile: %w", err)
	}
	fset := token.NewFileSet()
	astFile, err := parser.ParseFile(fset, path, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse source file: target parser.ParseFile(): %w", err)
	}
	dir := filepath.Dir(path)
	entries, _ := os.ReadDir(dir)
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	targetBase := filepath.Base(path)
	var others []*parsedAST
	for _, e := range entries {
		name := e.Name()
		if name == targetBase {
			continue
		}
		if !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") || strings.HasPrefix(name, ".") {
			continue
		}
		otherPath := filepath.Join(dir, name)
		ofset := token.NewFileSet()
		of, err := parser.ParseFile(ofset, otherPath, nil, parser.ParseComments|parser.AllErrors)
		if err != nil {
			return nil, fmt.Errorf("Parser.Parse source file: other file parser.ParseFile: %w", err)
		}
		others = append(others, &parsedAST{path: otherPath, file: of, fset: ofset})
	}
	// Collect ASTs with matching package, sorted by path.
	all := []*parsedAST{{path: path, file: astFile, src: src, fset: fset}}
	for _, o := range others {
		if o.file.Name.Name == astFile.Name.Name {
			all = append(all, o)
		}
	}
	sort.Slice(all, func(i, j int) bool { return all[i].path < all[j].path })
	ctx := &context{typeSpecs: map[string]*ast.TypeSpec{}, typeParams: map[string]ast.Expr{}}
	for _, pf := range all {
		for _, decl := range pf.file.Decls {
			switch d := decl.(type) {
			case *ast.GenDecl:
				if d.Tok == token.TYPE {
					for _, spec := range d.Specs {
						ts := spec.(*ast.TypeSpec)
						if _, ok := ctx.typeSpecs[ts.Name.Name]; !ok {
							ctx.typeSpecs[ts.Name.Name] = ts
						}
						if ts.TypeParams != nil {
							for _, field := range ts.TypeParams.List {
								for _, n := range field.Names {
									if _, ok := ctx.typeParams[n.Name]; !ok {
										ctx.typeParams[n.Name] = field.Type
									}
								}
							}
						}
					}
				}
			case *ast.FuncDecl:
				if d.Type.TypeParams != nil {
					for _, field := range d.Type.TypeParams.List {
						for _, n := range field.Names {
							if _, ok := ctx.typeParams[n.Name]; !ok {
								ctx.typeParams[n.Name] = field.Type
							}
						}
					}
				}
			}
		}
	}
	var functions []*models.Function
	for _, decl := range astFile.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		functions = append(functions, ctx.buildFunction(fd, src, fset))
	}
	if functions == nil {
		functions = []*models.Function{}
	}
	// Directory imports: target imports repeated via sorted matching files.
	var dirImports []*models.Import
	for _, pf := range all {
		dirImports = append(dirImports, importsOf(pf.file)...)
	}
	headerImports := []*models.Import{}
	headerImports = append(headerImports, importsOf(astFile)...)
	headerImports = append(headerImports, dirImports...)
	header := &models.Header{Comments: packageComments(astFile), Package: astFile.Name.Name, Imports: headerImports}
	return &SourceFile{Header: header, Functions: functions, Path: path, Dir: dir}, nil
}

func (p *Parser) ParseTestFile(srcPath string) (*TestFile, error) {
	testPath := TestPath(srcPath)
	if _, err := os.Stat(testPath); err != nil {
		return &TestFile{Exists: false, FuncNames: map[string]bool{}, Path: testPath}, nil
	}
	b, err := os.ReadFile(testPath)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse test file: ioutil.ReadFile: %w", err)
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, testPath, b, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("Parser.Parse test file: target parser.ParseFile(): %w", err)
	}
	var endPos token.Pos
	if len(f.Imports) > 0 {
		endPos = f.Imports[len(f.Imports)-1].End()
	} else {
		endPos = f.Name.End()
	}
	start := int(endPos) + 1
	var code []byte
	if start <= len(b) {
		code = b[start:]
	} else {
		code = []byte{}
	}
	funcNames := map[string]bool{}
	for _, decl := range f.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			funcNames[fd.Name.Name] = true
		}
	}
	header := &models.Header{Comments: packageComments(f), Package: f.Name.Name, Imports: importsOf(f)}
	header.Code = code
	return &TestFile{Exists: true, Header: header, FuncNames: funcNames, Path: testPath}, nil
}

// ---- function building ----

func (ctx *context) buildFunction(fd *ast.FuncDecl, src []byte, fset *token.FileSet) *models.Function {
	fn := &models.Function{Name: fd.Name.Name, IsExported: ast.IsExported(fd.Name.Name), Parameters: []*models.Field{}, Results: []*models.Field{}, TypeParams: []*models.TypeParam{}}
	// receiver
	if fd.Recv != nil && len(fd.Recv.List) > 0 {
		field := fd.Recv.List[0]
		name := ""
		if len(field.Names) > 0 {
			name = field.Names[0].Name
		}
		recvField := &models.Field{Name: name, Type: ctx.parseExpression(field.Type), Index: 0}
		fields := ctx.structFieldsFor(field.Type)
		if fields == nil {
			fields = []*models.Field{}
		}
		fn.Receiver = &models.Receiver{Field: recvField, Fields: fields}
	}
	fn.Parameters = ctx.flatten(fd.Type.Params)
	// results, removing errors
	rawResults := ctx.flatten(fd.Type.Results)
	for _, r := range rawResults {
		if r.Type.String() == "error" {
			fn.ReturnsError = true
			continue
		}
		r.Index = len(fn.Results)
		fn.Results = append(fn.Results, r)
	}
	// type params
	if fd.Type.TypeParams != nil && len(fd.Type.TypeParams.List) > 0 {
		for _, field := range fd.Type.TypeParams.List {
			for _, n := range field.Names {
				fn.TypeParams = append(fn.TypeParams, &models.TypeParam{Name: n.Name, Constraint: types.ExprString(field.Type)})
			}
		}
	} else if fn.Receiver != nil {
		// receiver type parameters from the type declaration
		base, args := receiverBaseAndArgs(fd.Recv.List[0].Type)
		if spec, ok := ctx.typeSpecs[base]; ok && spec.TypeParams != nil {
			flatParams := []*models.TypeParam{}
			for _, field := range spec.TypeParams.List {
				for _, n := range field.Names {
					flatParams = append(flatParams, &models.TypeParam{Name: n.Name, Constraint: types.ExprString(field.Type)})
				}
			}
			for i, arg := range args {
				if ident, ok := arg.(*ast.Ident); ok && i < len(flatParams) {
					fn.TypeParams = append(fn.TypeParams, &models.TypeParam{Name: ident.Name, Constraint: flatParams[i].Constraint})
				}
			}
		}
	}
	if fd.Body != nil {
		s := offset(fset, fd.Body.Pos())
		e := offset(fset, fd.Body.End())
		if s >= 0 && e >= s && e <= len(src) {
			fn.Body = string(src[s:e])
		}
	}
	return fn
}

func (ctx *context) flatten(list *ast.FieldList) []*models.Field {
	out := []*models.Field{}
	if list == nil {
		return out
	}
	idx := 0
	for _, field := range list.List {
		if len(field.Names) == 0 {
			out = append(out, &models.Field{Name: "", Type: ctx.parseExpression(field.Type), Index: idx})
			idx++
			continue
		}
		for _, n := range field.Names {
			out = append(out, &models.Field{Name: n.Name, Type: ctx.parseExpression(field.Type), Index: idx})
			idx++
		}
	}
	return out
}

func receiverBaseAndArgs(e ast.Expr) (string, []ast.Expr) {
	switch t := e.(type) {
	case *ast.StarExpr:
		return receiverBaseAndArgs(t.X)
	case *ast.Ident:
		return t.Name, nil
	case *ast.SelectorExpr:
		return t.Sel.Name, nil
	case *ast.IndexExpr:
		base, _ := receiverBaseAndArgs(t.X)
		return base, []ast.Expr{t.Index}
	case *ast.IndexListExpr:
		base, _ := receiverBaseAndArgs(t.X)
		return base, t.Indices
	case *ast.ParenExpr:
		return receiverBaseAndArgs(t.X)
	}
	return "", nil
}

func (ctx *context) structFieldsFor(recvType ast.Expr) []*models.Field {
	base, _ := receiverBaseAndArgs(recvType)
	return ctx.structFieldsByName(base, map[string]bool{})
}

func (ctx *context) structFieldsByName(name string, seen map[string]bool) []*models.Field {
	if name == "" || seen[name] {
		return nil
	}
	seen[name] = true
	spec, ok := ctx.typeSpecs[name]
	if !ok {
		return nil
	}
	if spec.TypeParams != nil && len(spec.TypeParams.List) > 0 {
		return nil
	}
	switch t := spec.Type.(type) {
	case *ast.StructType:
		return ctx.flattenStruct(t)
	case *ast.Ident:
		return ctx.structFieldsByName(t.Name, seen)
	}
	return nil
}

func (ctx *context) flattenStruct(st *ast.StructType) []*models.Field {
	out := []*models.Field{}
	idx := 0
	for _, field := range st.Fields.List {
		if len(field.Names) == 0 {
			out = append(out, &models.Field{Name: embeddedName(field.Type), Type: ctx.parseExpression(field.Type), Index: idx})
			idx++
			continue
		}
		for _, n := range field.Names {
			out = append(out, &models.Field{Name: n.Name, Type: ctx.parseExpression(field.Type), Index: idx})
			idx++
		}
	}
	return out
}

func embeddedName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return t.Sel.Name
	case *ast.StarExpr:
		return embeddedName(t.X)
	case *ast.IndexExpr:
		return embeddedName(t.X)
	case *ast.IndexListExpr:
		return embeddedName(t.X)
	case *ast.ParenExpr:
		return embeddedName(t.X)
	}
	return ""
}

// ---- expressions ----

func (ctx *context) parseExpression(e ast.Expr) *models.Expression {
	switch t := e.(type) {
	case *ast.StarExpr:
		value := types.ExprString(t.X)
		var underlying string
		switch t.X.(type) {
		case *ast.Ident, *ast.IndexExpr, *ast.IndexListExpr, *ast.SelectorExpr:
			underlying = ctx.underlyingTop(t.X, map[string]bool{})
		default:
			underlying = types.ExprString(t.X)
		}
		return &models.Expression{Value: value, IsStar: true, Underlying: underlying}
	case *ast.Ellipsis:
		inner := ctx.parseExpression(t.Elt)
		return &models.Expression{Value: inner.Value, IsStar: inner.IsStar, IsVariadic: true, Underlying: inner.Underlying}
	default:
		txt := types.ExprString(e)
		return &models.Expression{Value: txt, Underlying: ctx.underlyingTop(e, map[string]bool{}), IsWriter: txt == "io.Writer"}
	}
}

var basicTypes = map[string]bool{
	"bool": true, "byte": true, "complex64": true, "complex128": true,
	"float32": true, "float64": true, "int": true, "int8": true, "int16": true,
	"int32": true, "int64": true, "rune": true, "string": true, "uint": true,
	"uint8": true, "uint16": true, "uint32": true, "uint64": true, "uintptr": true,
}

func (ctx *context) underlyingTop(e ast.Expr, seen map[string]bool) string {
	switch t := e.(type) {
	case *ast.Ident:
		return ctx.underlyingIdent(t.Name, seen)
	case *ast.SelectorExpr:
		return ""
	case *ast.StarExpr:
		switch t.X.(type) {
		case *ast.Ident, *ast.IndexExpr, *ast.IndexListExpr, *ast.SelectorExpr:
			return ctx.underlyingTop(t.X, seen)
		default:
			return types.ExprString(t.X)
		}
	case *ast.Ellipsis:
		return ctx.underlyingTop(t.Elt, seen)
	case *ast.IndexExpr:
		return ctx.underlyingGeneric([]ast.Expr{t.Index}, t.X, seen, true)
	case *ast.IndexListExpr:
		return ctx.underlyingGeneric(t.Indices, t.X, seen, true)
	case *ast.ParenExpr:
		return ctx.underlyingTop(t.X, seen)
	default:
		txt := types.ExprString(e)
		if strings.Contains(txt, ".") {
			return ""
		}
		return txt
	}
}

func (ctx *context) underlyingIdent(name string, seen map[string]bool) string {
	if seen[name] {
		return ""
	}
	if c, ok := ctx.typeParams[name]; ok {
		seen[name] = true
		return ctx.underlyingConstraint(c, seen)
	}
	if spec, ok := ctx.typeSpecs[name]; ok {
		seen[name] = true
		return ctx.underlyingDefined(spec.Type, seen)
	}
	switch name {
	case "any":
		return "any"
	case "comparable":
		return "interface{comparable}"
	case "error":
		return "interface{Error() string}"
	}
	if basicTypes[name] {
		return name
	}
	return ""
}

func (ctx *context) underlyingDefined(e ast.Expr, seen map[string]bool) string {
	switch t := e.(type) {
	case *ast.Ident:
		return ctx.underlyingIdent(t.Name, seen)
	case *ast.SelectorExpr:
		return "invalid type"
	case *ast.IndexExpr:
		return ctx.underlyingGeneric([]ast.Expr{t.Index}, t.X, seen, false)
	case *ast.IndexListExpr:
		return ctx.underlyingGeneric(t.Indices, t.X, seen, false)
	case *ast.ParenExpr:
		return ctx.underlyingDefined(t.X, seen)
	default:
		return expandSelectors(e)
	}
}

// expandSelectors replaces selector expressions with "invalid type".
func expandSelectors(e ast.Expr) string {
	txt := types.ExprString(e)
	var sels []string
	seen := map[string]bool{}
	ast.Inspect(e, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			s := types.ExprString(sel)
			if !seen[s] {
				seen[s] = true
				sels = append(sels, s)
			}
			return false
		}
		return true
	})
	// longest first to avoid partial replacements
	sort.Slice(sels, func(i, j int) bool { return len(sels[i]) > len(sels[j]) })
	for _, s := range sels {
		txt = strings.ReplaceAll(txt, s, "invalid type")
	}
	return txt
}

func (ctx *context) underlyingGeneric(args []ast.Expr, baseExpr ast.Expr, seen map[string]bool, top bool) string {
	if top {
		for _, a := range args {
			if strings.Contains(types.ExprString(a), ".") {
				return ""
			}
		}
	}
	baseName, _ := receiverBaseAndArgs(baseExpr)
	spec, ok := ctx.typeSpecs[baseName]
	if !ok || spec.TypeParams == nil {
		return ""
	}
	// build substitution map
	var paramNames []string
	for _, field := range spec.TypeParams.List {
		for _, n := range field.Names {
			paramNames = append(paramNames, n.Name)
		}
	}
	subst := map[string]string{}
	for i, pn := range paramNames {
		if i < len(args) {
			if top {
				subst[pn] = types.ExprString(args[i])
			} else {
				if _, isSel := args[i].(*ast.SelectorExpr); isSel {
					subst[pn] = "invalid type"
				} else {
					subst[pn] = types.ExprString(args[i])
				}
			}
		}
	}
	var baseUnder string
	switch spec.Type.(type) {
	case *ast.Ident:
		baseUnder = ctx.underlyingIdent(spec.Type.(*ast.Ident).Name, seen)
	default:
		baseUnder = ctx.underlyingDefined(spec.Type, seen)
	}
	return substituteIdents(baseUnder, subst)
}

func (ctx *context) underlyingConstraint(c ast.Expr, seen map[string]bool) string {
	switch t := c.(type) {
	case *ast.Ident:
		switch t.Name {
		case "any":
			return "any"
		case "comparable":
			return "interface{comparable}"
		case "error":
			return "interface{Error() string}"
		}
		if basicTypes[t.Name] {
			return t.Name
		}
		if spec, ok := ctx.typeSpecs[t.Name]; ok {
			if _, isIface := spec.Type.(*ast.InterfaceType); isIface {
				return expandSelectors(spec.Type)
			}
			return t.Name
		}
		return "interface{}"
	case *ast.SelectorExpr:
		return "interface{}"
	default:
		return types.ExprString(c)
	}
}

// substituteIdents replaces identifier tokens in s according to subst,
// skipping identifiers immediately preceded by a dot.
func substituteIdents(s string, subst map[string]string) string {
	if len(subst) == 0 {
		return s
	}
	var b strings.Builder
	i := 0
	for i < len(s) {
		ch := s[i]
		if ch == '_' || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || ch >= 0x80 {
			j := i + 1
			for j < len(s) {
				c := s[j]
				if c == '_' || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c >= 0x80 {
					j++
				} else {
					break
				}
			}
			word := s[i:j]
			// check preceding non-space char
			prev := byte(0)
			for k := i - 1; k >= 0; k-- {
				if s[k] != ' ' && s[k] != '\t' {
					prev = s[k]
					break
				}
			}
			if rep, ok := subst[word]; ok && prev != '.' {
				b.WriteString(rep)
			} else {
				b.WriteString(word)
			}
			i = j
			continue
		}
		b.WriteByte(ch)
		i++
	}
	return b.String()
}

// SubstituteTypeParams is exported for generators.
func SubstituteTypeParams(s string, subst map[string]string) string {
	return substituteIdents(s, subst)
}

