function.arguments:
{"command":"cd /workspace && cat > generate.go <<'EOF'
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"gotestsreimpl/internal/ai"
	"gotestsreimpl/internal/goparser"
	"gotestsreimpl/internal/models"
)

type genOptions struct {
	printInputs bool
	subtests    bool
	parallel    bool
	named       bool
	useGoCmp    bool
	testify     bool
}

type funcGen struct {
	fn          *models.Function
	testName    string
	recvName    string
	nonWriter   []*models.Field
	writerParams []*models.Field
	opts        genOptions
	aiCases     []ai.TestCase
	subst       map[string]string
}

func titleFirst(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	if len(r) == 0 {
		return s
	}
	// upper case first rune
	c := r[0]
	if c >= 'a' && c <= 'z' {
		c = c - 'a' + 'A'
	} else if c > 127 {
		// use strings.Title-like for unicode letters via simple mapping
		c = []rune(strings.ToUpper(string(c)))[0]
	}
	r[0] = c
	return string(r)
}

func displayParamName(f *models.Field) string {
	if f.Name == "" || f.Name == "_" {
		return fmt.Sprintf("in%d", f.Index)
	}
	return f.Name
}

func receiverBaseName(fn *models.Function) string {
	if fn.Receiver == nil || fn.Receiver.Field == nil || fn.Receiver.Field.Type == nil {
		return ""
	}
	v := fn.Receiver.Field.Type.Value
	if i := strings.Index(v, "["); i >= 0 {
		v = v[:i]
	}
	if i := strings.LastIndex(v, "."); i >= 0 {
		v = v[i+1:]
	}
	return v
}

func receiverDisplayName(fn *models.Function) string {
	if fn.Receiver == nil {
		return ""
	}
	name := fn.Receiver.Field.Name
	if name == "" || name == "_" {
		name = fn.Receiver.ShortName()
	}
	if name == "t" {
		name = "tr"
	}
	return name
}

func concreteForConstraint(constraint string, constraintExprKind string) string {
	// constraintExprKind unused; logic works on raw constraint string via parsing below
	return constraint
}

// constraintToConcrete computes a concrete type for a type parameter
// from its constraint expression text. The constraint text was produced
// with types.ExprString, so some structure is still recognisable.
func constraintToConcrete(c string) string {
	c = strings.TrimSpace(c)
	switch c {
	case "any":
		return "int"
	case "comparable":
		return "string"
	}
	// selector: pkg.Name
	if strings.Contains(c, ".") && !strings.Contains(c, " ") && !strings.Contains(c, "{") {
		parts := strings.Split(c, ".")
		sel := parts[len(parts)-1]
		switch sel {
		case "Ordered", "Signed", "Unsigned", "Integer", "Float", "Complex":
			return "int"
		default:
			return "string"
		}
	}
	// union: take left side verbatim
	if strings.Contains(c, " | ") {
		left := strings.Split(c, " | ")[0]
		return strings.TrimSpace(left)
	}
	if strings.HasPrefix(c, "~") && !strings.Contains(c, "{") {
		return strings.TrimSpace(strings.TrimPrefix(c, "~"))
	}
	if strings.HasPrefix(c, "interface{") || strings.HasPrefix(c, "interface{") {
		// interface{~X} -> keep whole; otherwise string
		inner := strings.TrimPrefix(c, "interface{")
		inner = strings.TrimSuffix(inner, "}")
		inner = strings.TrimSpace(inner)
		if strings.HasPrefix(inner, "~") && !strings.Contains(inner, ";") && !strings.Contains(inner, "|") {
			return c
		}
		if strings.Contains(inner, "~") {
			// interface with a tilde element among others: keep whole if tilde is direct element
			parts := strings.Split(inner, ";")
			for _, p := range parts {
				if strings.HasPrefix(strings.TrimSpace(p), "~") {
					return c
				}
			}
		}
		return "string"
	}
	// anything else (idents like int, named constraints, *int, []byte, parens, etc)
	return "string"
}

func buildFuncGen(fn *models.Function, opts genOptions, aiCases []ai.TestCase) *funcGen {
	g := &funcGen{fn: fn, testName: fn.TestName(), recvName: receiverDisplayName(fn), opts: opts, aiCases: aiCases}
	for _, p := range fn.Parameters {
		if p.Type != nil && p.Type.IsWriter {
			g.writerParams = append(g.writerParams, p)
		} else {
			g.nonWriter = append(g.nonWriter, p)
		}
	}
	// substitution map
	subst := map[string]string{}
	for _, tp := range fn.TypeParams {
		subst[tp.Name] = constraintToConcrete(tp.Constraint)
	}
	g.subst = subst
	return g
}

func (g *funcGen) renderType(f *models.Field) string {
	if f == nil || f.Type == nil {
		return ""
	}
	s := f.Type.String()
	return goparser.SubstituteTypeParams(s, g.subst)
}

func (g *funcGen) recvTypeRendered() string {
	if g.fn.Receiver == nil {
		return ""
	}
	return goparser.SubstituteTypeParams(g.fn.Receiver.Field.Type.String(), g.subst)
}

func (g *funcGen) recvLocalType() string {
	s := g.recvTypeRendered()
	s = strings.TrimPrefix(s, "*")
	return s
}

func gotWantNames(f *models.Field) (got, want string) {
	if f.Name != "" && f.Name != "_" {
		suf := titleFirst(f.Name)
		return "got" + suf, "want" + suf
	}
	if f.Index == 0 {
		return "got", "want"
	}
	return fmt.Sprintf("got%d", f.Index), fmt.Sprintf("want%d", f.Index)
}

func (g *funcGen) writerGotWant(p *models.Field, writerIdx int) (got, want string) {
	if p.Name != "" && p.Name != "_" {
		suf := titleFirst(p.Name)
		return "got" + suf, "want" + suf
	}
	combined := len(g.fn.Results) + writerIdx
	if combined == 0 {
		return "got", "want"
	}
	return fmt.Sprintf("got%d", combined), fmt.Sprintf("want%d", combined)
}

func (g *funcGen) messageName() string {
	if g.fn.Receiver != nil {
		return g.fn.Receiver.Field.Type.Value + "." + g.fn.Name
	}
	return g.fn.Name
}

func (g *funcGen) messageWithInputs() string {
	msg := g.messageName() + "("
	if g.opts.printInputs && len(g.fn.Parameters) > 0 {
		var ph []string
		for range g.fn.Parameters {
			ph = append(ph, "%v")
		}
		msg += strings.Join(ph, ", ")
	}
	msg += ")"
	return msg
}

func (g *funcGen) inputsArgs() []string {
	if !g.opts.printInputs {
		return nil
	}
	var out []string
	for _, p := range g.fn.Parameters {
		out = append(out, "tt.args."+displayParamName(p))
	}
	return out
}

func (g *funcGen) callExpr() string {
	var target string
	if g.fn.Receiver != nil {
		if len(g.fn.Receiver.Fields) > 0 || g.fn.Receiver.IsStruct() {
			target = g.recvName + "." + g.fn.Name
		} else {
			target = "tt." + g.recvName + "." + g.fn.Name
		}
	} else {
		target = g.fn.Name
		if len(g.fn.TypeParams) > 0 {
			var conc []string
			for _, tp := range g.fn.TypeParams {
				conc = append(conc, constraintToConcrete(tp.Constraint))
			}
			target += "[" + strings.Join(conc, ", ") + "]"
		}
	}
	var args []string
	for _, p := range g.fn.Parameters {
		if p.Type != nil && p.Type.IsWriter {
			args = append(args, displayParamName(p))
		} else {
			a := "tt.args." + displayParamName(p)
			if p.Type != nil && p.Type.IsVariadic {
				a += "..."
			}
			args = append(args, a)
		}
	}
	return target + "(" + strings.Join(args, ", ") + ")"
}

func isBasicType(f *models.Field) bool {
	if f == nil || f.Type == nil {
		return false
	}
	switch f.Type.Underlying {
	case "bool", "string", "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "uintptr", "float32", "float64", "complex64", "complex128", "byte", "rune":
		return true
	}
	return false
}

// format prefix for error messages
func (g *funcGen) errFormatPrefix() string {
	if !g.opts.subtests {
		return "%q. "
	}
	return ""
}

func (g *funcGen) errArgsPrefix() []string {
	if !g.opts.subtests {
		return []string{"tt.name"}
	}
	return nil
}

func joinArgs(parts ...[]string) []string {
	var out []string
	for _, p := range parts {
		out = append(out, p...)
	}
	return out
}

func formatStringLit(s string) string {
	// s already includes % placeholders etc; need a Go quoted string.
	// Use strconv.Quote but preserve % signs.
	return strconv.Quote(s)
}

// generateFunction generates the (unformatted) test function text.
func (g *funcGen) generateFunction() string {
	fn := g.fn
	var b strings.Builder
	b.WriteString(fmt.Sprintf("func %s(t *testing.T) {\n", g.testName))
	if g.opts.parallel && !g.opts.subtests {
		b.WriteString("\tt.Parallel()\n")
	}
	// fields type
	if fn.Receiver != nil && len(fn.Receiver.Fields) > 0 {
		b.WriteString("\ttype fields struct {\n")
		for _, fd := range fn.Receiver.Fields {
			b.WriteString("\t\t" + fieldsStructEntry(fd, g) + "\n")
		}
		b.WriteString("\t}\n")
	}
	if len(g.nonWriter) > 0 {
		b.WriteString("\ttype args struct {\n")
		for _, p := range g.nonWriter {
			b.WriteString(fmt.Sprintf("\t\t%s %s\n", displayParamName(p), g.renderType(p)))
		}
		b.WriteString("\t}\n")
	}
	// tests table
	tableFields := g.tableFields()
	if g.opts.named {
		b.WriteString("\ttests := map[string]struct {\n")
		if len(tableFields) == 0 {
			b.WriteString("\n")
		}
	} else {
		b.WriteString("\ttests := []struct {\n")
	}
	for _, tf := range tableFields {
		b.WriteString("\t\t" + tf + "\n")
	}
	b.WriteString("\t}{\n")
	// test cases
	if len(g.aiCases) > 0 && !g.opts.testify {
		b.WriteString(g.renderAICases())
	} else {
		b.WriteString("\t\t// TODO: Add test cases.\n")
	}
	b.WriteString("\t}\n")
	// loop
	b.WriteString(g.loopHeader())
	inner := g.innerBody()
	if g.opts.subtests {
		nameExpr := "tt.name"
		if g.opts.named {
			nameExpr = "name"
		}
		b.WriteString(fmt.Sprintf("\t\tt.Run(%s, func(t *testing.T) {\n", nameExpr))
		if g.opts.parallel {
			b.WriteString("\t\t\tt.Parallel()\n")
		}
		b.WriteString(inner)
		b.WriteString("\t\t})\n")
	} else {
		b.WriteString(inner)
	}
	b.WriteString("\t}\n")
	b.WriteString("}\n")
	return b.String()
}

func (g *funcGen) tableFields() []string {
	fn := g.fn
	var out []string
	if !g.opts.named {
		out = append(out, "name string")
	}
	if fn.Receiver != nil {
		if len(fn.Receiver.Fields) > 0 {
			out = append(out, "fields fields")
		} else {
			out = append(out, fmt.Sprintf("%s %s", g.recvName, g.recvTypeRendered()))
		}
	}
	if len(g.nonWriter) > 0 {
		out = append(out, "args args")
	}
	for _, r := range fn.Results {
		_, want := gotWantNames(r)
		out = append(out, fmt.Sprintf("%s %s", want, g.renderType(r)))
	}
	for i, wp := range g.writerParams {
		_, want := g.writerGotWant(wp, i)
		out = append(out, fmt.Sprintf("%s string", want))
	}
	if fn.ReturnsError {
		if g.opts.testify {
			out = append(out, "assertion assert.ErrorAssertionFunc")
		} else {
			out = append(out, "wantErr bool")
		}
	}
	return out
}

func fieldsStructEntry(fd *models.Field, g *funcGen) string {
	typ := g.renderType(fd)
	// type rendering for struct fields should use the function substitution also
	if fd.Name == "_" {
		return fmt.Sprintf("%s %s", typ, typ)
	}
	if fd.Name == "" {
		return typ
	}
	return fmt.Sprintf("%s %s", fd.Name, typ)
}

func (g *funcGen) usesTT() bool {
	// Determine if the loop body references tt.
	fn := g.fn
	if len(g.nonWriter) > 0 || len(fn.Results) > 0 || len(g.writerParams) > 0 || fn.ReturnsError {
		return true
	}
	if fn.Receiver != nil {
		// fields case uses tt.fields, non-struct uses tt.<recv>, struct-empty: body does not use tt except inside t.Run (handled elsewhere)
		if len(fn.Receiver.Fields) > 0 {
			return true
		}
		if !fn.Receiver.IsStruct() {
			return true
		}
		// struct receiver with no other tt use: receiver created from empty literal
		return false
	}
	return false
}

func (g *funcGen) loopHeader() string {
	if g.opts.named {
		if g.opts.subtests {
			return "\tfor name, tt := range tests {\n"
		}
		// nosubtests
		if g.usesTT() {
			return "\tfor name, tt := range tests {\n"
		}
		return "\tfor range tests {\n"
	}
	if g.opts.subtests {
		return "\tfor _, tt := range tests {\n"
	}
	if g.usesTT() {
		return "\tfor _, tt := range tests {\n"
	}
	return "\tfor range tests {\n"
}

func (g *funcGen) renderAICases() string {
	var b strings.Builder
	for _, c := range g.aiCases {
		if g.opts.named {
			b.WriteString("\t\t" + strconv.Quote(c.Name) + ": {\n")
		} else {
			b.WriteString("\t\t{\n")
		}
		writeField := func(format string, args ...interface{}) {
			b.WriteString("\t\t\t" + fmt.Sprintf(format, args...) + "\n")
		}
		if !g.opts.named {
			writeField("name: %s,", strconv.Quote(c.Name))
		}
		// receiver
		if g.fn.Receiver != nil {
			if len(g.fn.Receiver.Fields) > 0 {
				b.WriteString("\t\t\tfields: fields{\n")
				for _, fd := range g.fn.Receiver.Fields {
					nm := fd.Name
					if nm == "" {
						nm = fd.Type.String()
					}
					b.WriteString(fmt.Sprintf("\t\t\t\t%s: nil, // TODO: Initialize from AI case\n", nm))
				}
				b.WriteString("\t\t\t},\n")
			} else {
				writeField("%s: nil, // TODO: Initialize receiver from AI case", g.recvName)
			}
		}
		if len(g.nonWriter) > 0 {
			b.WriteString("\t\t\targs: args{\n")
			for _, p := range g.nonWriter {
				dn := displayParamName(p)
				b.WriteString(fmt.Sprintf("\t\t\t\t%s: %s,\n", dn, c.Args[dn]))
			}
			b.WriteString("\t\t\t},\n")
		}
		for _, r := range g.fn.Results {
			_, want := gotWantNames(r)
			b.WriteString(fmt.Sprintf("\t\t\t%s: %s,\n", want, c.Want[want]))
		}
		for i, wp := range g.writerParams {
			_, want := g.writerGotWant(wp, i)
			b.WriteString(fmt.Sprintf("\t\t\t%s: %s,\n", want, c.Want[want]))
		}
		if g.fn.ReturnsError {
			b.WriteString(fmt.Sprintf("\t\t\twantErr: %v,\n", c.WantErr))
		}
		b.WriteString("\t\t},\n")
	}
	return b.String()
}

// innerBody returns the body inside the loop (with leading tabs for one level)
func (g *funcGen) innerBody() string {
	var lines []string
	indent := "\t\t"
	if g.opts.subtests {
		indent = "\t\t\t"
	}
	add := func(s string) { lines = append(lines, indent+s) }
	// receiver setup
	fn := g.fn
	if fn.Receiver != nil && len(fn.Receiver.Fields) > 0 {
		prefix := ""
		if fn.Receiver.Field.Type.IsStar {
			prefix = "&"
		}
		add(fmt.Sprintf("%s := %s%s{", g.recvName, prefix, g.recvLocalType()))
		for _, fd := range fn.Receiver.Fields {
			left := fd.Name
			rightField := fd.Name
			if fd.Name == "_" {
				rightField = g.renderType(fd)
				// renderType returns type string; for "_" field tt.fields.<type>
				rightField = fd.Type.String()
				rightField = goparser.SubstituteTypeParams(rightField, g.subst)
			} else if fd.Name == "" {
				rightField = fd.Type.String()
				left = fd.Type.String()
			}
			lines = append(lines, indent+"\t"+fmt.Sprintf("%s: tt.fields.%s,", left, rightField))
		}
		add("}")
	} else if fn.Receiver != nil && fn.Receiver.IsStruct() {
		prefix := ""
		if fn.Receiver.Field.Type.IsStar {
			prefix = "&"
		}
		add(fmt.Sprintf("%s := %s%s{}", g.recvName, prefix, g.recvLocalType()))
	}
	for _, wp := range g.writerParams {
		add(fmt.Sprintf("%s := &bytes.Buffer{}", displayParamName(wp)))
	}
	if g.opts.testify {
		lines = append(lines, g.testifyBody(indent)...)
	} else {
		lines = append(lines, g.defaultBody(indent)...)
	}
	var b strings.Builder
	for _, l := range lines {
		b.WriteString(l + "\n")
	}
	return b.String()
}

func (g *funcGen) defaultBody(indent string) []string {
	var lines []string
	add := func(s string) { lines = append(lines, indent+s) }
	fn := g.fn
	call := g.callExpr()
	if !fn.ReturnsError {
		if len(fn.Results) == 0 {
			add(call)
			lines = append(lines, g.writerParamChecks(indent)...)
			return lines
		}
		if len(fn.Results) == 1 {
			r := fn.Results[0]
			got, want := gotWantNames(r)
			if r.Type.IsWriter {
				src := writerResultSource(r)
				add(fmt.Sprintf("if %s := %s.String(); %s != tt.%s {", got, src, got, want))
				lines = append(lines, indent+"\t"+g.resultErrorfLine(r, got, want))
				add("}")
			} else {
				cond := g.resultCondition(r, got, want)
				add(fmt.Sprintf("if %s := %s; %s {", got, call, cond))
				lines = append(lines, indent+"\t"+g.resultErrorfLine(r, got, want))
				add("}")
			}
			lines = append(lines, g.writerParamChecks(indent)...)
			return lines
		}
		// multiple results
		var gots []string
		for _, r := range fn.Results {
			got, _ := gotWantNames(r)
			gots = append(gots, got)
		}
		add(fmt.Sprintf("%s := %s", strings.Join(gots, ", "), call))
		for _, r := range fn.Results {
			lines = append(lines, g.resultCheckLines(indent, r)...)
		}
		lines = append(lines, g.writerParamChecks(indent)...)
		return lines
	}
	// returns error
	if len(fn.Results) == 0 {
		if len(g.writerParams) == 0 {
			// final only-error
			format, args := g.errorFormatAndArgs(true)
			add(fmt.Sprintf("if err := %s; (err != nil) != tt.wantErr {", call))
			lines = append(lines, indent+"\t"+fmt.Sprintf("t.Errorf(%s, %s)", formatStringLit(format), strings.Join(args, ", ")))
			add("}")
			return lines
		}
		// error + writers
		add(fmt.Sprintf("if err := %s; (err != nil) != tt.wantErr {", call))
		lines = append(lines, g.errorCheckBodyLines(indent)...)
		add("}")
		add("if tt.wantErr {")
		add("\treturn")
		add("}")
		lines = append(lines, g.writerParamChecks(indent)...)
		return lines
	}
	// results + error
	var gots []string
	for _, r := range fn.Results {
		got, _ := gotWantNames(r)
		gots = append(gots, got)
	}
	add(fmt.Sprintf("%s, err := %s", strings.Join(gots, ", "), call))
	add("if (err != nil) != tt.wantErr {")
	lines = append(lines, g.errorCheckBodyLines(indent)...)
	add("}")
	add("if tt.wantErr {")
	add("\treturn")
	add("}")
	for _, r := range fn.Results {
		lines = append(lines, g.resultCheckLines(indent, r)...)
	}
	lines = append(lines, g.writerParamChecks(indent)...)
	return lines
}

// errorCheckBodyLines returns the contents of the if (err...) block (with fatal/continue logic)
func (g *funcGen) errorCheckBodyLines(indent string) []string {
	format, args := g.errorFormatAndArgs(false)
	if g.opts.subtests {
		return []string{indent + "\t" + fmt.Sprintf("t.Fatalf(%s, %s)", formatStringLit(format), strings.Join(args, ", "))}
	}
	return []string{
		indent + "\t" + fmt.Sprintf("t.Errorf(%s, %s)", formatStringLit(format), strings.Join(args, ", ")),
		indent + "\t" + "continue",
	}
}

func (g *funcGen) errorFormatAndArgs(final bool) (string, []string) {
	// format string
	f := ""
	var args []string
	if !g.opts.subtests {
		f += "%q. "
		args = append(args, "tt.name")
	}
	f += g.messageWithInputs() + " error = %v, wantErr %v"
	args = append(args, g.inputsArgs()...)
	args = append(args, "err", "tt.wantErr")
	return f, args
}

func (g *funcGen) resultCondition(r *models.Field, got, want string) string {
	if isBasicType(r) {
		return fmt.Sprintf("%s != tt.%s", got, want)
	}
	if g.opts.useGoCmp {
		return fmt.Sprintf("!cmp.Equal(tt.%s, %s)", want, got)
	}
	return fmt.Sprintf("!reflect.DeepEqual(%s, tt.%s)", got, want)
}

func (g *funcGen) resultErrorfLine(r *models.Field, got, want string) string {
	f := ""
	var args []string
	if !g.opts.subtests {
		f += "%q. "
		args = append(args, "tt.name")
	}
	f += g.messageWithInputs()
	if len(g.fn.Results) > 1 {
		f += " " + got
	}
	f += " = %v, want %v"
	args = append(args, g.inputsArgs()...)
	args = append(args, got, "tt."+want)
	if g.opts.useGoCmp && !isBasicType(r) {
		f += "\ndiff=%s"
		args = append(args, fmt.Sprintf("cmp.Diff(tt.%s, %s)", want, got))
	}
	// need to render format string with literal \n as escape in source
	return fmt.Sprintf("t.Errorf(%s, %s)", quoteFormat(f), strings.Join(args, ", "))
}

func quoteFormat(f string) string {
	// Quote, but the generated source should contain \n literally for diff line.
	// strconv.Quote will turn an actual newline in f into \n, which is what we want.
	return strconv.Quote(f)
}

func (g *funcGen) resultCheckLines(indent string, r *models.Field) []string {
	got, want := gotWantNames(r)
	var lines []string
	if r.Type.IsWriter {
		src := writerResultSource(r)
		lines = append(lines, indent+fmt.Sprintf("if %s := %s.String(); %s != tt.%s {", got, src, got, want))
		lines = append(lines, indent+"\t"+g.resultErrorfLine(r, got, want))
		lines = append(lines, indent+"}")
		return lines
	}
	cond := g.resultCondition(r, got, want)
	lines = append(lines, indent+fmt.Sprintf("if %s {", cond))
	lines = append(lines, indent+"\t"+g.resultErrorfLine(r, got, want))
	lines = append(lines, indent+"}")
	return lines
}

func writerResultSource(r *models.Field) string {
	if r.Name != "" && r.Name != "_" {
		return r.Name
	}
	return fmt.Sprintf("in%d", r.Index)
}

func (g *funcGen) writerParamChecks(indent string) []string {
	var lines []string
	for i, wp := range g.writerParams {
		got, want := g.writerGotWant(wp, i)
		varName := displayParamName(wp)
		lines = append(lines, indent+fmt.Sprintf("if %s := %s.String(); %s != tt.%s {", got, varName, got, want))
		// error line
		f := ""
		var args []string
		if !g.opts.subtests {
			f += "%q. "
			args = append(args, "tt.name")
		}
		f += g.messageWithInputs() + " = %v, want %v"
		args = append(args, g.inputsArgs()...)
		args = append(args, got, "tt."+want)
		lines = append(lines, indent+"\t"+fmt.Sprintf("t.Errorf(%s, %s)", strconv.Quote(f), strings.Join(args, ", ")))
		lines = append(lines, indent+"}")
	}
	return lines
}

func (g *funcGen) testifyBody(indent string) []string {
	var lines []string
	add := func(s string) { lines = append(lines, indent+s) }
	fn := g.fn
	call := g.callExpr()
	assertLine := func(want string, expr string) string {
		return g.assertEqualLine(want, expr)
	}
	_ = assertLine
	if !fn.ReturnsError {
		if len(fn.Results) == 0 {
			add(call)
			lines = append(lines, g.testifyWriterChecks(indent)...)
			return lines
		}
		if len(fn.Results) == 1 {
			r := fn.Results[0]
			_, want := gotWantNames(r)
			var expr string
			if r.Type.IsWriter {
				expr = writerResultSource(r) + ".String()"
			} else {
				expr = call
			}
			add(g.assertEqualLine(want, expr))
			lines = append(lines, g.testifyWriterChecks(indent)...)
			return lines
		}
		var gots []string
		for _, r := range fn.Results {
			got, _ := gotWantNames(r)
			gots = append(gots, got)
		}
		add(fmt.Sprintf("%s := %s", strings.Join(gots, ", "), call))
		for _, r := range fn.Results {
			got, want := gotWantNames(r)
			expr := got
			if r.Type.IsWriter {
				expr = writerResultSource(r) + ".String()"
			}
			add(g.assertEqualLine(want, expr))
		}
		lines = append(lines, g.testifyWriterChecks(indent)...)
		return lines
	}
	// error
	if len(fn.Results) == 0 {
		add(g.assertionLine(call))
		lines = append(lines, g.testifyWriterChecks(indent)...)
		return lines
	}
	var gots []string
	for _, r := range fn.Results {
		got, _ := gotWantNames(r)
		gots = append(gots, got)
	}
	add(fmt.Sprintf("%s, err := %s", strings.Join(gots, ", "), call))
	add(g.assertionLine("err"))
	for _, r := range fn.Results {
		got, want := gotWantNames(r)
		expr := got
		if r.Type.IsWriter {
			expr = writerResultSource(r) + ".String()"
		}
		add(g.assertEqualLine(want, expr))
	}
	lines = append(lines, g.testifyWriterChecks(indent)...)
	return lines
}

func (g *funcGen) testifyWriterChecks(indent string) []string {
	var lines []string
	for i, wp := range g.writerParams {
		_, want := g.writerGotWant(wp, i)
		varName := displayParamName(wp)
		lines = append(lines, indent+g.assertEqualLine(want, varName+".String()"))
	}
	return lines
}

func (g *funcGen) assertEqualLine(want, expr string) string {
	if g.opts.subtests && !g.opts.printInputs {
		return fmt.Sprintf("assert.Equal(t, tt.%s, %s)", want, expr)
	}
	// Equalf
	f := ""
	var args []string
	if !g.opts.subtests {
		f += "%q. "
		args = append(args, "tt.name")
	}
	f += g.messageWithInputs()
	args = append(args, g.inputsArgs()...)
	if len(args) == 0 {
		return fmt.Sprintf("assert.Equalf(t, tt.%s, %s, %s)", want, expr, strconv.Quote(f))
	}
	return fmt.Sprintf("assert.Equalf(t, tt.%s, %s, %s, %s)", want, expr, strconv.Quote(f), strings.Join(args, ", "))
}

func (g *funcGen) assertionLine(expr string) string {
	if g.opts.subtests && !g.opts.printInputs {
		return fmt.Sprintf("tt.assertion(t, %s)", expr)
	}
	f := ""
	var args []string
	if !g.opts.subtests {
		f += "%q. "
		args = append(args, "tt.name")
	}
	f += g.messageWithInputs()
	args = append(args, g.inputsArgs()...)
	return fmt.Sprintf("tt.assertion(t, %s, fmt.Sprintf(%s, %s))", expr, strconv.Quote(f), strings.Join(args, ", "))
}

var _ = sort.Strings
EOF
