func processImports(src []byte, extraCandidates map[string]string) ([]byte, error) {
	tmpFile, err := os.CreateTemp("", "gotests_*")
	if err != nil {
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	tmpName := tmpFile.Name()
	tmpFile.Close()
	defer os.Remove(tmpName)
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, tmpName, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	// collect existing imports
	var specs []*importSpecInfo
	declBySpec := map[*ast.ImportSpec]*ast.GenDecl{}
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, sp := range gd.Specs {
			is := sp.(*ast.ImportSpec)
			name := ""
			if is.Name != nil {
				name = is.Name.Name
			}
			path, _ := strconv.Unquote(is.Path.Value)
			info := &importSpecInfo{name: name, path: path, decl: gd, spec: is}
			specs = append(specs, info)
			declBySpec[is] = gd
		}
	}
	// used selector names
	used := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				used[id.Name] = true
			}
		}
		return true
	})
	// locally declared identifiers (variables, types, funcs, params)
	locals := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		switch d := n.(type) {
		case *ast.FuncDecl:
			if d.Name != nil {
				locals[d.Name.Name] = true
			}
		case *ast.ValueSpec:
			for _, nm := range d.Names {
				locals[nm.Name] = true
			}
		case *ast.TypeSpec:
			if d.Name != nil {
				locals[d.Name.Name] = true
			}
		case *ast.AssignStmt:
			if d.Tok == token.DEFINE {
				for _, e := range d.Lhs {
					if id, ok := e.(*ast.Ident); ok {
						locals[id.Name] = true
					}
				}
			}
		case *ast.RangeStmt:
			if id, ok := d.Key.(*ast.Ident); ok {
				locals[id.Name] = true
			}
			if id, ok := d.Value.(*ast.Ident); ok {
				locals[id.Name] = true
			}
		case *ast.Field:
			for _, nm := range d.Names {
				locals[nm.Name] = true
			}
		}
		return true
	})
	// "tt" and other conventional locals are captured by Field/Range; but receiver variables in calls are fields.
	// package name derivation
	pkgNameOf := func(info *importSpecInfo) string {
		if info.name != "" && info.name != "." && info.name != "_" {
			return info.name
		}
		if info.name == "." || info.name == "_" {
			return info.name
		}
		// known std path?
		// derive from base
		base := info.path
		if i := strings.LastIndex(base, "/"); i >= 0 {
			base = base[i+1:]
		}
		// gopkg.in/yaml.v2 -> yaml
		if i := strings.Index(base, ".v"); i >= 0 {
			// check suffix is version like .v2
			rest := base[i+2:]
			isNum := rest != ""
			for _, ch := range rest {
				if ch < '0' || ch > '9' {
					isNum = false
				}
			}
			if isNum {
				base = base[:i]
			}
		}
		return base
	}
