	seen := map[string]bool{}
	keptNames := map[string]bool{}
	addFinal := func(name, path string, kept bool, decl *ast.GenDecl) {
		key := name + "\x00" + path
		if seen[key] {
			return
		}
		seen[key] = true
		finals = append(finals, &finalImport{name: name, path: path, kept: kept, decl: decl})
		if name != "" && name != "." && name != "_" {
			keptNames[name] = true
		} else if name == "" {
			// derive
			tmp := &importSpecInfo{name: name, path: path}
			keptNames[pkgNameOf(tmp)] = true
		}
	}
	for _, info := range specs {
		if info.name == "." || info.name == "_" {
			addFinal(info.name, info.path, true, info.decl)
			continue
		}
		pn := pkgNameOf(info)
		if used[pn] {
			addFinal(info.name, info.path, true, info.decl)
		} else {
			// if used selector has a name that could be this package but basename differs
			// e.g. path ends with -pkg and selector is pkg: check cleaned name
			clean := strings.ReplaceAll(pn, "-", "")
			if used[clean] {
				addFinal(info.name, info.path, true, info.decl)
			}
		}
	}
	// candidate map for additions
	candidates := map[string]string{}
	for k, v := range stdPackages {
		candidates[k] = v
	}
	// go-cmp cmp takes precedence over std cmp for our generated code when cmp is used as go-cmp?
	// Actually generated code for use_go_cmp refers to github.com/google/go-cmp/cmp.
	// If a "cmp" selector is used and no kept import named cmp, we need to decide.
	// We track extraCandidates passed from generation-time context.
	for k, v := range extraCandidates {
		candidates[k] = v
	}
	for k, v := range thirdPartyPackages {
		if _, ok := candidates[k]; !ok {
			candidates[k] = v
		}
	}
	// also existing specs provide candidates (alias / basename)
	for _, info := range specs {
		pn := pkgNameOf(info)
		if pn != "." && pn != "_" && pn != "" {
			if _, ok := candidates[pn]; !ok {
				candidates[pn] = info.path
			}
		}
		if info.name != "" && info.name != "." && info.name != "_" {
			candidates[info.name] = info.path
		}
	}
	// add missing, in sorted order for determinism
	var missing []string
	for name := range used {
		if keptNames[name] {
			continue
		}
		if locals[name] {
			continue
		}
		if _, ok := candidates[name]; ok {
			missing = append(missing, name)
		}
	}
	sort.Strings(missing)
	for _, name := range missing {
		addFinal("", candidates[name], false, nil)
		keptNames[name] = true
	}
	// Remove import declarations from source and insert new one after package.
	// Compute offsets
	fileStart := fset.PositionFor(file.Package, false).Offset
	_ = fileStart
	pkgEnd := fset.PositionFor(file.Name.End(), false).Offset
	// ranges to remove (only import decls)
	type rang struct{ s, e int }
	var ranges []rang
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		s := fset.PositionFor(gd.Pos(), false).Offset
		e := fset.PositionFor(gd.End(), false).Offset
		ranges = append(ranges, rang{s, e})
	}
	// Build new source without those ranges
	newSrc := removeRanges(src, ranges, pkgEnd)
	// Insert import block after package name offset (adjusted if removals before that none)
	insertAt := pkgEnd // removals all after package, so unchanged
	importText := buildImportText(finals)
	var outSrc []byte
	outSrc = append(outSrc, newSrc[:insertAt]...)
	if importText != "" {
		outSrc = append(outSrc, []byte("\n"+importText+"\n")...)
	}
	outSrc = append(outSrc, newSrc[insertAt:]...)
	formatted, err := format.Source(outSrc)
	if err != nil {
		// Try parsing with tmp name to produce a similar error message
		fs2 := token.NewFileSet()
		_, perr := parser.ParseFile(fs2, tmpName, outSrc, parser.ParseComments|parser.AllErrors)
		if perr != nil {
			return nil, fmt.Errorf("imports.Process: %w", perr)
		}
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	return formatted, nil
}

func removeRanges(src []byte, ranges []struct{ s, e int }, pkgEnd int) []byte {
	// ranges are in file order; remove from last to first
	// copy
	out := append([]byte(nil), src...)
	// sort descending by start
	sort.Slice(ranges, func(i, j int) bool { return ranges[i].s > ranges[j].s })
	for _, r := range ranges {
		if r.s < 0 || r.e > len(out) || r.s > r.e {
			continue
		}
		out = append(out[:r.s], out[r.e:]...)
	}
	return out
}

func buildImportText(finals []*finalImportLocal) string { return "" }

type finalImportLocal = struct {
	name string
	path string
	kept bool
	decl *ast.GenDecl
}
