	ast.Inspect(file, func(n ast.Node) bool {
		switch d := n.(type) {
		case *ast.FuncDecl:
			if d.Name != nil {
				locals[d.Name.Name] = true
			}
		case *ast.ValueSpec:
			for _, nm := range d.Names {
				locals[nm.Name] = true
			}
		case *ast.TypeSpec:
			if d.Name != nil {
