type importSpecInfo struct {
	name string
	path string
	decl *ast.GenDecl
	spec *ast.ImportSpec
}

type finalImport struct {
	name  string
	path  string
	kept  bool
	paren bool
}

func pkgNameFromPath(path string) string {
	base := path
	if i := strings.LastIndex(base, "/"); i >= 0 {
		base = base[i+1:]
	}
	if i := strings.Index(base, ".v"); i >= 0 {
		rest := base[i+2:]
		isNum := rest != ""
		for _, ch := range rest {
			if ch < '0' || ch > '9' {
				isNum = false
			}
		}
		if isNum {
			base = base[:i]
		}
	}
	return base
}

func processImports(src []byte, extraCandidates map[string]string) ([]byte, error) {
	tmpFile, err := os.CreateTemp("", "gotests_*")
	if err != nil {
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	tmpName := tmpFile.Name()
	tmpFile.Close()
	defer os.Remove(tmpName)
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, tmpName, src, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	var specs []*importSpecInfo
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, sp := range gd.Specs {
			is := sp.(*ast.ImportSpec)
			name := ""
			if is.Name != nil {
				name = is.Name.Name
			}
			path, _ := strconv.Unquote(is.Path.Value)
			specs = append(specs, &importSpecInfo{name: name, path: path, decl: gd, spec: is})
		}
	}
	used := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if id, ok := sel.X.(*ast.Ident); ok {
				used[id.Name] = true
			}
		}
		return true
	})
	locals := map[string]bool{}
	ast.Inspect(file, func(n ast.Node) bool {
		switch d := n.(type) {
		case *ast.FuncDecl:
			if d.Name != nil {
				locals[d.Name.Name] = true
			}
		case *ast.ValueSpec:
			for _, nm := range d.Names {
				locals[nm.Name] = true
			}
		case *ast.TypeSpec:
			if d.Name != nil {
				locals[d.Name.Name] = true
			}
		case *ast.AssignStmt:
			if d.Tok == token.DEFINE {
				for _, e := range d.Lhs {
					if id, ok := e.(*ast.Ident); ok {
						locals[id.Name] = true
					}
				}
			}
		case *ast.RangeStmt:
			if id, ok := d.Key.(*ast.Ident); ok {
				locals[id.Name] = true
			}
			if id, ok := d.Value.(*ast.Ident); ok {
				locals[id.Name] = true
			}
		case *ast.Field:
			for _, nm := range d.Names {
				locals[nm.Name] = true
			}
		}
		return true
	})
	pkgNameOf := func(info *importSpecInfo) string {
		if info.name != "" {
			return info.name
		}
		return pkgNameFromPath(info.path)
	}
	var finals []*finalImport
	seen := map[string]bool{}
	keptNames := map[string]bool{}
	addFinal := func(name, path string, kept bool, decl *ast.GenDecl) {
		key := name + "\x00" + path
		if seen[key] {
			return
		}
		seen[key] = true
		paren := false
		if decl != nil && decl.Lparen.IsValid() {
			paren = true
		}
		finals = append(finals, &finalImport{name: name, path: path, kept: kept, paren: paren})
		if name != "" && name != "." && name != "_" {
			keptNames[name] = true
		} else if name == "" {
			keptNames[pkgNameFromPath(path)] = true
		}
	}
	for _, info := range specs {
		if info.name == "." || info.name == "_" {
			addFinal(info.name, info.path, true, info.decl)
			continue
		}
		pn := pkgNameOf(info)
		if used[pn] || used[strings.ReplaceAll(pn, "-", "")] {
			addFinal(info.name, info.path, true, info.decl)
		}
	}
	candidates := map[string]string{}
	for k, v := range stdPackages {
		candidates[k] = v
	}
	for k, v := range thirdPartyPackages {
		candidates[k] = v
	}
	for k, v := range extraCandidates {
		candidates[k] = v
	}
	for _, info := range specs {
		pn := pkgNameOf(info)
		if pn != "." && pn != "_" && pn != "" {
			if _, ok := candidates[pn]; !ok {
				candidates[pn] = info.path
			}
		}
	}
	var missing []string
	for name := range used {
		if keptNames[name] || locals[name] {
			continue
		}
		if _, ok := candidates[name]; ok {
			missing = append(missing, name)
		}
	}
	sort.Strings(missing)
	for _, name := range missing {
		addFinal("", candidates[name], false, nil)
	}
	pkgEnd := fset.PositionFor(file.Name.End(), false).Offset
	type brange struct{ s, e int }
	var ranges []brange
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		s := fset.PositionFor(gd.Pos(), false).Offset
		e := fset.PositionFor(gd.End(), false).Offset
		ranges = append(ranges, brange{s, e})
	}
	newSrc := append([]byte(nil), src...)
	sort.Slice(ranges, func(i, j int) bool { return ranges[i].s > ranges[j].s })
	for _, r := range ranges {
		if r.s >= 0 && r.e <= len(newSrc) && r.s <= r.e {
			newSrc = append(newSrc[:r.s], newSrc[r.e:]...)
		}
	}
	importText := buildImportText(finals)
	var outSrc []byte
	outSrc = append(outSrc, newSrc[:pkgEnd]...)
	if importText != "" {
		outSrc = append(outSrc, []byte("\n"+importText+"\n")...)
	}
	outSrc = append(outSrc, newSrc[pkgEnd:]...)
	formatted, err := format.Source(outSrc)
	if err != nil {
		fs2 := token.NewFileSet()
		_, perr := parser.ParseFile(fs2, tmpName, outSrc, parser.ParseComments|parser.AllErrors)
		if perr != nil {
			return nil, fmt.Errorf("imports.Process: %w", perr)
		}
		return nil, fmt.Errorf("imports.Process: %w", err)
	}
	return formatted, nil
}

func buildImportText(finals []*finalImport) string {
	if len(finals) == 0 {
		return ""
	}
	// sort by group (std first), path, name
	isStd := func(p string) bool {
		first := p
		if i := strings.Index(first, "/"); i >= 0 {
			first = first[:i]
		}
		return !strings.Contains(first, ".")
	}
	sorted := append([]*finalImport(nil), finals...)
	sort.SliceStable(sorted, func(i, j int) bool {
		si, sj := isStd(sorted[i].path), isStd(sorted[j].path)
		if si != sj {
			return si
		}
		if sorted[i].path != sorted[j].path {
			return sorted[i].path < sorted[j].path
		}
		return sorted[i].name < sorted[j].name
	})
	render := func(f *finalImport) string {
		if f.name != "" {
			return f.name + " " + strconv.Quote(f.path)
		}
		return strconv.Quote(f.path)
	}
	if len(sorted) == 1 {
		f := sorted[0]
		if f.kept && f.paren {
			return "import (\n\t" + render(f) + "\n)"
		}
		// If the sole import came from a parenthesized decl but was added, format as single.
		// Kept single-line imports stay single.
		return "import " + render(f)
	}
	var b strings.Builder
	b.WriteString("import (\n")
	prevStd := isStd(sorted[0].path)
	for i, f := range sorted {
		std := isStd(f.path)
		if i > 0 && std != prevStd {
			b.WriteString("\n")
		}
		prevStd = std
		b.WriteString("\t" + render(f) + "\n")
	}
	b.WriteString(")")
	return b.String()
}
EOF
gofmt -w imports.go; echo ok"}

