package main

import (
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"text/template"

	"gotestsreimpl/internal/ai"
	"gotestsreimpl/internal/models"
)

type templateSet struct {
	tmpl *template.Template
}

type wrapperInfo struct {
	fn             *models.Function
	printInputs    bool
	subtests       bool
	parallel       bool
	named          bool
	useGoCmp       bool
	templateParams map[string]interface{}
	aiCases        []interface{}
}

func extractWrapper(v interface{}) wrapperInfo {
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Ptr {
		rv = rv.Elem()
	}
	info := wrapperInfo{}
	if rv.Kind() != reflect.Struct {
		return info
	}
	if rv.NumField() > 0 {
		if f, ok := rv.Field(0).Interface().(*models.Function); ok {
			info.fn = f
		}
	}
	if rv.NumField() > 7 {
		info.printInputs = rv.Field(1).Bool()
		info.subtests = rv.Field(2).Bool()
		info.parallel = rv.Field(3).Bool()
		info.named = rv.Field(4).Bool()
		info.useGoCmp = rv.Field(5).Bool()
		if m, ok := rv.Field(6).Interface().(map[string]interface{}); ok {
			info.templateParams = m
		}
		if a, ok := rv.Field(7).Interface().([]interface{}); ok {
			info.aiCases = a
		}
	}
	return info
}

func helperInputs(v interface{}) string {
	info := extractWrapper(v)
	if !info.printInputs || info.fn == nil {
		return ""
	}
	var parts []string
	for _, p := range info.fn.Parameters {
		parts = append(parts, "tt.args."+displayParamName(p)+", ")
	}
	return strings.Join(parts, "")
}

func helperMessage(v interface{}) string {
	info := extractWrapper(v)
	if info.fn == nil {
		return ""
	}
	g := buildFuncGen(info.fn, genOptions{printInputs: info.printInputs, subtests: info.subtests, parallel: info.parallel, named: info.named, useGoCmp: info.useGoCmp}, nil)
	return g.messageWithInputs()
}

func helperCall(v interface{}) string {
	info := extractWrapper(v)
	if info.fn == nil {
		return ""
	}
	g := buildFuncGen(info.fn, genOptions{printInputs: info.printInputs, subtests: info.subtests, parallel: info.parallel, named: info.named, useGoCmp: info.useGoCmp}, nil)
	return g.callExpr()
}

func helperResults(v interface{}) string {
	info := extractWrapper(v)
	if info.fn == nil {
		return "   "
	}
	if len(info.fn.Results) == 0 && !info.fn.ReturnsError {
		return "   "
	}
	var names []string
	for _, r := range info.fn.Results {
		got, _ := gotWantNames(r)
		names = append(names, got)
	}
	if info.fn.ReturnsError {
		names = append(names, "err")
	}
	return " " + strings.Join(names, ", ") + "  :=  "
}

func helperDefaultFunc(v interface{}) (string, error) {
	info := extractWrapper(v)
	if info.fn == nil {
		return "", nil
	}
	var cases []ai.TestCase
	for _, c := range info.aiCases {
		if tc, ok := c.(ai.TestCase); ok {
			cases = append(cases, tc)
		}
	}
	g := buildFuncGen(info.fn, genOptions{printInputs: info.printInputs, subtests: info.subtests, parallel: info.parallel, named: info.named, useGoCmp: info.useGoCmp}, cases)
	return "\n" + g.generateFunction(), nil
}

func newBaseTemplate() *template.Template {
	tmpl := template.New("gotests")
	tmpl.Funcs(template.FuncMap{
		"__gt_inputs":      helperInputs,
		"__gt_message":     helperMessage,
		"__gt_call":        helperCall,
		"__gt_results":     helperResults,
		"__gt_defaultFunc": helperDefaultFunc,
	})
	// header
	_, _ = tmpl.New("header.tmpl").Parse("{{define \"header\"}}{{range .Comments}}{{.}}\n{{end}}package {{.Package}}\n{{if .Imports}}\nimport (\n{{range .Imports}}{{if .Name}}{{.Name}} {{end}}{{.Path}}\n{{end}})\n{{end}}{{end}}")
	_, _ = tmpl.New("function.tmpl").Parse("{{define \"function\"}}{{__gt_defaultFunc .}}{{end}}")
	_, _ = tmpl.New("inputs.tmpl").Parse("{{define \"inputs\"}}{{__gt_inputs .}}{{end}}")
	_, _ = tmpl.New("results.tmpl").Parse("{{define \"results\"}}{{__gt_results .}}{{end}}")
	_, _ = tmpl.New("message.tmpl").Parse("{{define \"message\"}}{{__gt_message .}}{{end}}")
	_, _ = tmpl.New("call.tmpl").Parse("{{define \"call\"}}{{__gt_call .}}{{end}}")
	return tmpl
}

func loadTemplateDir(dir string) (*templateSet, error) {
	tmpl := newBaseTemplate()
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("loading custom templates: ioutil.ReadDir: %w", err)
	}
	var files []string
	for _, e := range entries {
		files = append(files, filepath.Join(dir, e.Name()))
	}
	if _, err := tmpl.ParseFiles(files...); err != nil {
		return nil, fmt.Errorf("loading custom templates: tmpls.ParseFiles: %w", err)
	}
	return &templateSet{tmpl: tmpl}, nil
}

func namedTemplateError(name string) error {
	// Simulate fs.Sub / templates.ParseFS behaviour of the embedded FS.
	// A name containing "." or ".." segments is invalid for fs.Sub.
	parts := strings.Split(name, "/")
	for _, p := range parts {
		if p == "." || p == ".." {
			return fmt.Errorf("loading custom templates of name: templates.Sub: sub %s: invalid argument", name)
		}
	}
	if strings.Contains(name, "*") {
		return fmt.Errorf("loading custom templates of name: templates.ParseFS: invalid result from inner fsys Glob:  not in %s", name)
	}
	return fmt.Errorf("loading custom templates of name: templates.ParseFS: template: pattern matches no files: `*.tmpl`")
}
EOF
gofmt -w templates.go; echo ok"}

