func extractWrapper(v interface{}) wrapperInfo {
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Ptr {
		rv = rv.Elem()
	}
	info := wrapperInfo{}
	if rv.Kind() != reflect.Struct {
		return info
	}
	if rv.NumField() > 0 {
