// Build AI prompts, parse and validate responses.

type parseErrWithResponse struct {
	err      string
	response string
}

func aiFunctionCode(fn *models.Function) string {
	var b strings.Builder
	b.WriteString("func ")
	if fn.Receiver != nil {
		b.WriteString("(" + fn.Receiver.Field.Name + " " + fn.Receiver.Field.Type.String() + ") ")
		// reconstruct above with correct spacing below is overwritten by logic:
		// Instead build explicitly:
		b.Reset()
		b.WriteString("func ")
		b.WriteString("(" + fn.Receiver.Field.Name + " " + fn.Receiver.Field.Type.String() + ") ")
	}
	b.WriteString(fn.Name)
	b.WriteString("(")
	var params []string
	for _, p := range fn.Parameters {
		if p.Name != "" {
			params = append(params, p.Name+" "+p.Type.String())
		} else {
			params = append(params, p.Type.String())
		}
	}
	b.WriteString(strings.Join(params, ", "))
	b.WriteString(")")
	var resultTypes []string
	for _, r := range fn.Results {
		resultTypes = append(resultTypes, r.Type.String())
	}
	if fn.ReturnsError {
		resultTypes = append(resultTypes, "error")
	}
	if len(resultTypes) == 1 {
		b.WriteString(" " + resultTypes[0])
	} else if len(resultTypes) > 1 {
		b.WriteString(" (" + strings.Join(resultTypes, ", ") + ")")
	}
	if fn.Body != "" {
		b.WriteString(" " + fn.Body)
	}
	return b.String()
}

type scaffoldField struct {
	name string
	typ  string
}

func aiScaffold(fn *models.Function, g *funcGen) (string, []scaffoldField, []scaffoldField) {
	// returns scaffold text, struct fields, pseudo-result fields
	var fields []scaffoldField
	fields = append(fields, scaffoldField{"name", "string"})
	if fn.Receiver != nil {
		fields = append(fields, scaffoldField{"c", fn.Receiver.Field.Type.String()})
	}
	if len(g.nonWriter) > 0 {
		fields = append(fields, scaffoldField{"args", "args"})
	}
	var pseudo []scaffoldField
	for i, r := range fn.Results {
		name := "want"
		if i > 0 {
			name = fmt.Sprintf("want%d", i)
		}
		pseudo = append(pseudo, scaffoldField{name, r.Type.String()})
	}
	for idx, wp := range g.writerParams {
		combined := len(fn.Results) + idx
		name := "want"
		if combined > 0 {
			name = fmt.Sprintf("want%d", combined)
		}
		_ = wp
		pseudo = append(pseudo, scaffoldField{name, "string"})
	}
	fields = append(fields, pseudo...)
	if fn.ReturnsError {
		fields = append(fields, scaffoldField{"wantErr", "bool"})
	}
	var b strings.Builder
	b.WriteString("tests := []struct {\n")
	for _, f := range fields {
		b.WriteString("\t" + f.name + " " + f.typ + "\n")
	}
	b.WriteString("} {\n\t// TODO: Add test cases.\n}")
	return b.String(), fields, pseudo
}

func buildPrompt(fn *models.Function, opts genOptions, minCases, maxCases int, prevErr error, prevResp string, prevIsParse bool) string {
	g := buildFuncGen(fn, opts, nil)
	scaffold, _, _ := aiScaffold(fn, g)
	funcCode := aiFunctionCode(fn)
	var example strings.Builder
	example.WriteString("{\n")
	example.WriteString("    name: \"descriptive test name\",\n")
	if fn.Receiver != nil {
		recvLocal := strings.TrimPrefix(fn.Receiver.Field.Type.String(), "*")
		example.WriteString(fmt.Sprintf("    c: &%s{},\n", recvLocal))
	}
	if len(g.nonWriter) > 0 {
		var ps []string
		for _, p := range g.nonWriter {
			ps = append(ps, fmt.Sprintf("%s: <value>", p.Name))
		}
		example.WriteString(fmt.Sprintf("    args: args{%s},\n", strings.Join(ps, ", ")))
	}
	// pseudo results
	_, _, pseudo := aiScaffold(fn, g)
	for _, pf := range pseudo {
		example.WriteString(fmt.Sprintf("    %s: <expected_value>,\n", pf.name))
	}
	if fn.ReturnsError {
		example.WriteString("    wantErr: false,\n")
	}
	example.WriteString("},")
	include := "valid inputs, edge cases (zero/empty/nil), boundary values."
	if fn.ReturnsError {
		include = "1 valid case, 1 edge case, 1 error case."
	}
	var b strings.Builder
	b.WriteString("You are a Go testing expert. Generate test cases for the following function.\n\n")
	b.WriteString("Function to test:\n```go\n")
	b.WriteString(funcCode + "\n")
	b.WriteString("```\n\n")
	b.WriteString("Here is the test scaffold:\n```go\n")
	b.WriteString(scaffold + "\n")
	b.WriteString("```\n\n")
	b.WriteString(fmt.Sprintf("Generate between %d and %d test cases. Each test case must have UNIQUE, DIFFERENT input values.\n", minCases, maxCases))
	b.WriteString("Include: " + include + "\n\n")
	b.WriteString("Example format:\n```go\n")
	b.WriteString(example.String() + "\n")
	b.WriteString("```\n\n")
	b.WriteString("Requirements:\n")
	b.WriteString("- DIFFERENT values in each test case (NO duplicates)\n")
	b.WriteString("- Use NAMED fields (e.g., field: value)\n")
	b.WriteString("- Use exact field names from scaffold\n")
	b.WriteString("- Use natural language test names with spaces (e.g., \"valid input\", not \"valid_input\")\n")
	b.WriteString("- Valid Go syntax, realistic values\n")
	if fn.ReturnsError {
		b.WriteString("- Set wantErr based on expected error\n")
	}
	b.WriteString("\nOutput ONLY the test case array, no explanations:\n")
	if prevErr != nil {
		b.WriteString("PREVIOUS ATTEMPT FAILED:\n")
		b.WriteString(prevErr.Error() + "\n")
		if prevIsParse {
			b.WriteString("\nLLM Response:\n")
			b.WriteString(prevResp + "\n")
		}
		b.WriteString("\nPlease fix the above issue.\n\n")
		b.WriteString("Now fill in the scaffold above by replacing '// TODO: Add test cases.' with your test cases:\n")
	} else {
		b.WriteString("Now fill in the scaffold above by replacing '// TODO: Add test cases.' with your test cases:\n")
	}
	b.WriteString("```go\n")
	b.WriteString(scaffold + "\n")
	b.WriteString("```\n")
	return b.String()
}

var fenceRe = regexp.MustCompile("(?s)```(?:go|golang)?[ \t]*\n?(.*?)```")

func cleanAIResponse(resp string) string {
	if strings.Contains(resp, "```") {
		m := fenceRe.FindStringSubmatch(resp)
		if m != nil {
			return m[1]
		}
		// unterminated fence: take after first fence line
		idx := strings.Index(resp, "```")
		rest := resp[idx+3:]
		if nl := strings.Index(rest, "\n"); nl >= 0 {
			// strip language line if present
			first := strings.TrimSpace(rest[:nl])
			if first == "go" || first == "golang" || first == "" {
				rest = rest[nl+1:]
			}
		}
		return rest
	}
	return resp
}

func parseAICases(resp string) ([]ai.TestCase, *parseErrWithResponse) {
	cleaned := cleanAIResponse(resp)
	wrapper := "package main\n\ntype args struct{}\n\nfunc _() {\n\t_ = []interface{}{\n\t_ = []interface{}{\n\n" + cleaned + "\n\t}\n}\n"
	// wrapper places cleaned starting at line 10; adjust to line 9 by removing one placeholder line if needed
	// Our wrapper: count: 1 package,2 blank,3 type,4 blank,5 func,6 _,7 _,8 blank,9 cleaned.
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "test.go", wrapper, parser.ParseComments|parser.AllErrors)
	if err != nil {
		return nil, &parseErrWithResponse{err: fmt.Sprintf("parse Go test cases: parse Go code: %s", err.Error()), response: resp}
	}
	var cases []ai.TestCase
	found := false
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		// check if it has a name key
		hasName := false
		for _, el := range cl.Elts {
			if kv, ok := el.(*ast.KeyValueExpr); ok {
				if id, ok := kv.Key.(*ast.Ident); ok && id.Name == "name" {
					hasName = true
				}
			}
		}
		if !hasName {
			return true
		}
		found = true
		tc := ai.TestCase{Args: map[string]string{}, Want: map[string]string{}}
		for _, el := range cl.Elts {
			kv, ok := el.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			keyId, ok := kv.Key.(*ast.Ident)
			if !ok {
				continue
			}
			key := keyId.Name
			switch {
			case key == "name":
				if bl, ok := kv.Value.(*ast.BasicLit); ok && bl.Kind == token.STRING {
					if unq, err := strconv.Unquote(bl.Value); err == nil {
						tc.Name = unq
					} else {
						tc.Name = strings.Trim(bl.Value, "\"")
					}
				} else {
					// preserve non-string literal text as name
					tc.Name = exprSource(wrapper, fset, kv.Value)
				}
			case key == "args":
				if sub, ok := kv.Value.(*ast.CompositeLit); ok {
					for _, subEl := range sub.Elts {
						if skv, ok := subEl.(*ast.KeyValueExpr); ok {
							if sid, ok := skv.Key.(*ast.Ident); ok {
								tc.Args[sid.Name] = exprSource(wrapper, fset, skv.Value)
							}
						}
					}
				}
			case key == "wantErr":
				if id, ok := kv.Value.(*ast.Ident); ok && id.Name == "true" {
					tc.WantErr = true
				}
			case strings.HasPrefix(key, "want"):
				tc.Want[key] = exprSource(wrapper, fset, kv.Value)
			default:
				// ignored
			}
		}
		cases = append(cases, tc)
		return false // don't descend into this case
	})
	if !found || len(cases) == 0 {
		return nil, &parseErrWithResponse{err: "parse Go test cases: no test cases found in response", response: resp}
	}
	return cases, nil
}

func exprSource(src string, fset *token.FileSet, e ast.Expr) string {
	s := fset.PositionFor(e.Pos(), false).Offset
	en := fset.PositionFor(e.End(), false).Offset
	if s >= 0 && en >= s && en <= len(src) {
		raw := src[s:en]
		// normalise using format if possible for a standalone expression? Keep raw; final formatting will handle.
		// But composite literals from AI may be on one line; leaving raw is fine.
		return strings.TrimSpace(raw)
	}
	// fallback: format node
	var b strings.Builder
	_ = format.Node(&b, fset, e)
	return b.String()
}

func validateAICases(cases []ai.TestCase, fn *models.Function, g *funcGen) error {
	expectedWant := len(fn.Results) + len(g.writerParams)
	for _, tc := range cases {
		for _, p := range g.nonWriter {
			key := p.Name
			if _, ok := tc.Args[key]; !ok {
				return fmt.Errorf("test case %q missing argument: %s", tc.Name, key)
			}
		}
		if len(tc.Want) != expectedWant {
			return fmt.Errorf("test case %q has %d return values, expected %d", tc.Name, len(tc.Want), expectedWant)
		}
	}
	return nil
}

// generateAICasesForFunction performs up to 3 attempts.
func generateAICasesForFunction(provider *ai.Provider, fn *models.Function, opts genOptions, minCases, maxCases int) ([]ai.TestCase, error) {
	g := buildFuncGen(fn, opts, nil)
	var prevErr error
	var prevResp string
	var prevIsParse bool
	var lastErr error
	var lastParse *parseErrWithResponse
	for attempt := 0; attempt < 3; attempt++ {
		prompt := buildPrompt(fn, opts, minCases, maxCases, prevErr, prevResp, prevIsParse)
		resp, err := provider.Generate(prompt)
		if err != nil {
			lastErr = err
			prevErr = err
			prevIsParse = false
			prevResp = ""
			lastParse = nil
			continue
		}
		cases, perr := parseAICases(resp)
		if perr != nil {
			lastErr = fmt.Errorf("%s", perr.err)
			lastParse = perr
			prevErr = lastErr
			prevResp = resp
			prevIsParse = true
			continue
		}
		if verr := validateAICases(cases, fn, g); verr != nil {
			lastErr = verr
			prevErr = verr
			prevIsParse = false
			prevResp = ""
			lastParse = nil
			continue
		}
		return cases, nil
	}
	if lastParse != nil {
		return nil, fmt.Errorf("failed after 3 attempts: %s\n\nLLM Response:\n%s", lastParse.err, lastParse.response)
	}
	return nil, fmt.Errorf("failed after 3 attempts: %w", lastErr)
}

var _ = os.Getenv
EOF
gofmt -w ai_generate.go; echo ok"}

