		aiMin           = flag.Int("ai-min-cases", 3, "minimum number of test cases to generate with AI")
		aiModel         = flag.String("ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
		allFlag         = flag.Bool("all", false, "generate tests for all functions and methods")
		exclFlag        = flag.String("excl", "", "regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
		exportedFlag    = flag.Bool("exported", false, "generate tests for exported functions and methods. Takes precedence over -only and -all")
		iFlag           = flag.Bool("i", false, "print test inputs in error messages")
		namedFlag       = flag.Bool("named", false, "switch table tests from using slice to map (with test name for the key)")
		nosubtestsFlag  = flag.Bool("nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
		onlyFlag        = flag.String("only", "", "regexp. generate tests for functions and methods that match only. Takes precedence over -all")
		parallelFlag    = flag.Bool("parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
		templateFlag    = flag.String("template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
		templateDirFlag = flag.String("template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
		templateParams  = flag.String("template_params", "", "read external parameters to template by json with stdin")
		templateParamsF = flag.String("template_params_file", "", "read external parameters to template by json with file")
		useGoCmpFlag    = flag.Bool("use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
		versionFlag     = flag.Bool("version", false, "print version information and exit")
		wFlag           = flag.Bool("w", false, "write output to (test) files instead of stdout")
	)
	flag.Parse()
	if *versionFlag {
		fmt.Print(versionOutput)
		return
	}
	if *aiFlag {
