				fmt.Print(string(out.contents))
			}
		}
	}
}

func osReadFile(name string) ([]byte, error) {
	return os.ReadFile(name)
}

func writeFile(name string, b []byte) error {
	return os.WriteFile(name, b, 0644)
}

// inputFiles expands one argument into a list of Go source files.
func inputFiles(arg string) ([]string, error) {
	abs, err := filepath.Abs(arg)
	if err != nil {
		abs = arg
	}
	// recursive pattern: final segment is "..."
	if filepath.Base(abs) == "..." {
		root := filepath.Dir(abs)
		var files []string
		err := filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				return err
			}
			if info.IsDir() {
				if path != root && strings.HasPrefix(info.Name(), ".") {
					return filepath.SkipDir
				}
				return nil
			}
			if isGoFileForDir(path) {
				files = append(files, path)
			}
			return nil
		})
		if err != nil {
			return nil, fmt.Errorf("input.Files: filepath.Walk: %w", err)
		}
		return files, nil
	}
	info, err := os.Stat(abs)
	if err != nil {
		// original error string ends with a newline, so Println adds another
		return nil, fmt.Errorf("input.Files: %w\n", err)
	}
	if info.IsDir() {
		entries, err := os.ReadDir(abs)
		if err != nil {
			return nil, nil
		}
		var files []string
		for _, e := range entries {
			name := e.Name()
			if !isGoFileNameForDir(name) {
				continue
			}
			files = append(files, filepath.Join(abs, name))
		}
		return files, nil
	}
	if !isGoFileName(arg) || strings.HasPrefix(filepath.Base(abs), ".") {
		return nil, fmt.Errorf("input.Files: no Go source files found at %s", abs)
	}
	return []string{abs}, nil
}

func isGoFileName(path string) bool {
	return strings.HasSuffix(path, ".go")
}

func isGoFileNameForDir(name string) bool {
	if strings.HasPrefix(name, ".") {
		return false
	}
	if !strings.HasSuffix(name, ".go") {
		return false
	}
	if strings.HasSuffix(name, "_test.go") {
		return false
	}
	return true
}

func isGoFileForDir(path string) bool {
	return isGoFileNameForDir(filepath.Base(path))
}

