{"command":"cd /workspace && python3 - <<'PY'
import pathlib
p=pathlib.Path("internal/goparser/goparser.go"); t=p.read_text()
old='''func packageComments(f *ast.File) []string {
	var out []string
	for _, g := range f.Comments {
		if g.Pos() >= f.Package {
			continue
		}
		for _, c := range g.List {
			out = append(out, c.Text)
		}
	}
	return out
}'''
new='''func packageComments(f *ast.File) []string {
	return packageCommentsWithFset(f, nil)
}

func packageCommentsWithFset(f *ast.File, fset *token.FileSet) []string {
	var groups []*ast.CommentGroup
	for _, g := range f.Comments {
		if g.Pos() >= f.Package {
			continue
		}
		groups = append(groups, g)
	}
	var out []string
	lineOf := func(pos token.Pos) int {
		if fset == nil {
			return 0
		}
		return fset.PositionFor(pos, false).Line
	}
	for i, g := range groups {
		for _, c := range g.List {
			out = append(out, c.Text)
		}
		if fset != nil {
			var nextPos token.Pos
			if i+1 < len(groups) {
				nextPos = groups[i+1].Pos()
			} else {
				nextPos = f.Package
			}
			if lineOf(nextPos)-lineOf(g.End()) > 1 {
				out = append(out, "")
			}
		}
	}
	return out
}'''
assert old in t; t=t.replace(old,new)
t=t.replace('header := &models.Header{Comments: packageComments(astFile), Package: astFile.Name.Name, Imports: headerImports}','header := &models.Header{Comments: packageCommentsWithFset(astFile, fset), Package: astFile.Name.Name, Imports: headerImports}')
t=t.replace('header := &models.Header{Comments: packageComments(f), Package: f.Name.Name, Imports: importsOf(f)}','header := &models.Header{Comments: packageCommentsWithFset(f, fset), Package: f.Name.Name, Imports: importsOf(f)}')
p.write_text(t)
PY
go build -o /tmp/myexe . && python3 /tmp/compare3.py 2>&1 | grep -E "buildtags|comments|existing_single|recursion|w_dir|help|badflag|expr""}

