			parts = append(parts, "import "+render(f))
		} else {
			parts = append(parts, buildImportTextNoC(others))
		}
	}
	return strings.Join(parts, "\\n")
}

func buildImportTextNoC(finals []*finalImport) string {
	if len(finals) == 0 {
		return ""
	}
	isStd := func(p string) bool {
		first := p
		if i := strings.Index(first, "/"); i >= 0 {
			first = first[:i]
		}
		return !strings.Contains(first, ".")
	}
	sorted := append([]*finalImport(nil), finals...)
	sort.SliceStable(sorted, func(i, j int) bool {
		si, sj := isStd(sorted[i].path), isStd(sorted[j].path)
		if si != sj {
			return si
		}
		if sorted[i].path != sorted[j].path {
			return sorted[i].path < sorted[j].path
		}
		return sorted[i].name < sorted[j].name
	})
	render := func(f *finalImport) string {
		if f.name != "" {
			return f.name + " " + strconv.Quote(f.path)
		}
		return strconv.Quote(f.path)
	}
	if len(sorted) == 1 {
		f := sorted[0]
		if f.kept && f.paren {
			return "import (\\n\\t" + render(f) + "\\n)"
		}
		return "import " + render(f)
	}
	var b strings.Builder
	b.WriteString("import (\\n")
	prevStd := isStd(sorted[0].path)
	for i, f := range sorted {
		std := isStd(f.path)
		if i > 0 && std != prevStd {
			b.WriteString("\\n")
		}
		prevStd = std
		b.WriteString("\\t" + render(f) + "\\n")
	}
	b.WriteString(")")
	return b.String()
}
